-- 4. Questions -------------------------------------------------------------
INSERT INTO public.quiz_questions (id, quiz_id, question, kind, options, correct_index, explanation, position)
SELECT v.id, v.quiz_id, v.question, v.kind, v.options, v.correct_index, v.explanation, v.position
  FROM (VALUES
    ('5e95bd55-c518-5e30-87df-53a1b432d445'::uuid, '043dc49b-7106-57bf-9962-f95891ebc9f4'::uuid, 'Combien de couches compte le modèle TCP/IP ?', 'mcq', '["Quatre","Sept","Trois","Cinq"]'::jsonb, 0, 'Accès réseau, Internet, transport et application. Le modèle OSI, lui, en compte sept.', 1),
    ('dbcaee24-319f-52e3-8f08-9b8afa1e91ef'::uuid, '043dc49b-7106-57bf-9962-f95891ebc9f4'::uuid, 'Quelle est la différence essentielle entre TCP et UDP ?', 'mcq', '["TCP garantit la remise et l’ordre des données, UDP non","TCP est plus rapide qu’UDP","UDP chiffre les données","TCP ne fonctionne que sur Wi-Fi"]'::jsonb, 0, 'UDP convient au direct vidéo, où une donnée en retard ne sert plus à rien.', 2),
    ('c012086a-c4af-5d6c-ab2c-49211a9ace12'::uuid, '043dc49b-7106-57bf-9962-f95891ebc9f4'::uuid, 'Quel algorithme le protocole OSPF utilise-t-il ?', 'mcq', '["L’algorithme de Dijkstra","L’algorithme de Bellman-Ford","Le tri rapide","La recherche dichotomique"]'::jsonb, 0, 'Il calcule le plus court chemin en tenant compte du coût des liens.', 3),
    ('15a49687-9d74-522f-934b-cb7dff24586d'::uuid, '043dc49b-7106-57bf-9962-f95891ebc9f4'::uuid, 'Quelle est la limite du nombre de sauts dans le protocole RIP ?', 'mcq', '["15","32","64","Il n’y en a pas"]'::jsonb, 0, 'Au-delà, la destination est considérée comme inaccessible.', 4),
    ('c5ef35e4-3720-5a8b-85ed-641e86b51482'::uuid, '043dc49b-7106-57bf-9962-f95891ebc9f4'::uuid, 'Qu’est-ce qu’un interblocage entre deux processus ?', 'mcq', '["Chacun détient la ressource que l’autre attend","Un processus consomme tout le processeur","Un processus écrase la mémoire d’un autre","Un processus se termine sans libérer la mémoire"]'::jsonb, 0, 'Aucun des deux ne peut avancer : le système est bloqué.', 5),
    ('ca214409-918f-52b4-98b2-864842bce371'::uuid, '043dc49b-7106-57bf-9962-f95891ebc9f4'::uuid, 'Un processus est un programme en cours d’exécution.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il dispose de son propre espace mémoire, isolé des autres par le système.', 6),
    ('b8db9b88-ced6-581a-8c61-4129580bd798'::uuid, '043dc49b-7106-57bf-9962-f95891ebc9f4'::uuid, 'Que fait une couche du modèle TCP/IP aux données qu’elle reçoit de la couche supérieure ?', 'mcq', '["Elle les encapsule en y ajoutant son en-tête","Elle les chiffre systématiquement","Elle les compresse","Elle les supprime après envoi"]'::jsonb, 0, 'À l’arrivée, les en-têtes sont retirés dans l’ordre inverse.', 7),
    ('e0038a96-19fe-57e1-b14d-77a08c71c438'::uuid, '043dc49b-7106-57bf-9962-f95891ebc9f4'::uuid, 'Le protocole RIP tient compte du débit des liens.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ne compte que les sauts : c’est justement ce qu’OSPF corrige.', 8),
    ('7095aede-da93-54b9-9c2b-01c5d6392021'::uuid, '6f0b2168-5960-5640-bd3c-cc5cb6a4b64a'::uuid, 'Dans un chiffrement asymétrique, quelle clé sert à chiffrer un message destiné à quelqu’un ?', 'mcq', '["Sa clé publique","Sa clé privée","Une clé partagée à l’avance","La clé du serveur"]'::jsonb, 0, 'Seule sa clé privée permettra ensuite de le déchiffrer.', 1),
    ('afb1dec3-ee7f-51f9-aa60-2f5bcf4d055f'::uuid, '6f0b2168-5960-5640-bd3c-cc5cb6a4b64a'::uuid, 'Pourquoi HTTPS combine-t-il chiffrement asymétrique et symétrique ?', 'mcq', '["L’asymétrique sert à échanger une clé de session, le symétrique à chiffrer les échanges","Pour doubler la sécurité","Parce que le symétrique n’est pas sûr","Pour compresser les données"]'::jsonb, 0, 'L’asymétrique est bien plus lent : on ne l’emploie que pour la mise en place.', 2),
    ('6e489f15-8841-51a4-9ec4-9046773f5589'::uuid, '6f0b2168-5960-5640-bd3c-cc5cb6a4b64a'::uuid, 'Qu’est-ce qu’une fonction de hachage ?', 'mcq', '["Une fonction à sens unique produisant une empreinte de taille fixe","Un algorithme de chiffrement réversible","Un protocole de transport","Une méthode de compression"]'::jsonb, 0, 'La moindre modification du message change entièrement l’empreinte.', 3),
    ('09a23c39-62a4-55d3-9f8d-36823d1ac94a'::uuid, '6f0b2168-5960-5640-bd3c-cc5cb6a4b64a'::uuid, 'Un mot de passe doit être stocké chiffré et déchiffrable par le serveur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est stocké sous forme d’empreinte, salée : le serveur n’a pas besoin de le retrouver.', 4),
    ('fe7043ec-804d-58bb-bafa-9087941a7227'::uuid, '6f0b2168-5960-5640-bd3c-cc5cb6a4b64a'::uuid, 'Que garantit une signature numérique ?', 'mcq', '["L’origine et l’intégrité du message","La confidentialité du message","La rapidité de transmission","L’anonymat de l’émetteur"]'::jsonb, 0, 'L’émetteur chiffre l’empreinte avec sa clé privée : chacun peut vérifier avec la publique.', 5),
    ('728808af-e13c-5020-8f9e-19e3f33b9b01'::uuid, '6f0b2168-5960-5640-bd3c-cc5cb6a4b64a'::uuid, 'À quoi sert une autorité de certification ?', 'mcq', '["À signer un certificat liant une clé publique à une identité","À chiffrer les communications","À filtrer les ports réseau","À stocker les mots de passe"]'::jsonb, 0, 'Sans elle, rien n’empêcherait un attaquant de publier une clé au nom d’un autre.', 6),
    ('b0bb1870-8120-590a-aec7-2005dc9b618a'::uuid, '6f0b2168-5960-5640-bd3c-cc5cb6a4b64a'::uuid, 'En quoi consiste une attaque de l’homme du milieu ?', 'mcq', '["L’attaquant s’intercale entre deux interlocuteurs et relaie leurs messages","Il sature le serveur de requêtes","Il devine le mot de passe par force brute","Il chiffre les données de la victime"]'::jsonb, 0, 'Le certificat sert précisément à la rendre détectable.', 7),
    ('7e9b20ef-3a09-58e6-88a8-07ef7deaa552'::uuid, '6f0b2168-5960-5640-bd3c-cc5cb6a4b64a'::uuid, 'À quoi sert le sel ajouté avant le hachage d’un mot de passe ?', 'mcq', '["À empêcher les attaques par dictionnaire précalculé","À rendre le hachage réversible","À raccourcir l’empreinte","À chiffrer la base de données"]'::jsonb, 0, 'Deux mots de passe identiques donnent alors deux empreintes différentes.', 8),
    ('f7b761b4-8518-5573-a5c2-3105177a6fe8'::uuid, 'f8f20075-1e71-5dbe-bfde-9e32c30d3ed2'::uuid, 'Qu’est-ce qu’un type abstrait de données ?', 'mcq', '["Un jeu d’opérations défini indépendamment de son implémentation","Une classe Python sans attribut","Un tableau de taille variable","Une donnée non typée"]'::jsonb, 0, 'C’est le principe d’encapsulation appliqué aux structures de données.', 1),
    ('256852cf-8686-5cd0-8f1e-f5b05198860b'::uuid, 'f8f20075-1e71-5dbe-bfde-9e32c30d3ed2'::uuid, 'Quelle structure fonctionne en « dernier entré, premier sorti » ?', 'mcq', '["La pile","La file","Le dictionnaire","L’arbre"]'::jsonb, 0, 'La file, elle, est « premier entré, premier sorti ».', 2),
    ('f52b2646-ea3e-52f0-a9ce-b75270ab0b13'::uuid, 'f8f20075-1e71-5dbe-bfde-9e32c30d3ed2'::uuid, 'Quelle structure est utilisée pour un parcours en largeur ?', 'mcq', '["La file","La pile","Le dictionnaire","Le tableau trié"]'::jsonb, 0, 'Le parcours en profondeur, lui, s’appuie sur une pile.', 3),
    ('9d086084-8b3e-58bc-8734-221c287c65f7'::uuid, 'f8f20075-1e71-5dbe-bfde-9e32c30d3ed2'::uuid, 'Quel est le coût d’accès au i-ième élément d’une liste chaînée ?', 'mcq', '["Linéaire : il faut parcourir la chaîne","Constant","Logarithmique","Quadratique"]'::jsonb, 0, 'C’est l’inverse du tableau, qui offre un accès direct.', 4),
    ('db76ba0f-8791-5675-b320-e7322958eada'::uuid, 'f8f20075-1e71-5dbe-bfde-9e32c30d3ed2'::uuid, 'Quel est le coût moyen d’une recherche dans un dictionnaire ?', 'mcq', '["Constant","Linéaire","Logarithmique","Quadratique"]'::jsonb, 0, 'Grâce au hachage de la clé.', 5),
    ('8294d0de-9ea4-5f9c-9e0b-32576e4c8232'::uuid, 'f8f20075-1e71-5dbe-bfde-9e32c30d3ed2'::uuid, 'Insérer un élément en tête d’une liste chaînée coûte un temps constant.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il suffit de créer un maillon et de le faire pointer vers l’ancienne tête.', 6),
    ('a963f7ac-9397-5dc2-8bb6-7cefc386985d'::uuid, 'f8f20075-1e71-5dbe-bfde-9e32c30d3ed2'::uuid, 'Quelle structure choisir pour retrouver une valeur à partir d’un identifiant ?', 'mcq', '["Le dictionnaire","La pile","La file","La liste chaînée"]'::jsonb, 0, 'C’est exactement ce que le type associatif est fait pour faire.', 7),
    ('e4a87a17-7ac7-503d-b1c8-903cd7f65ab2'::uuid, 'f8f20075-1e71-5dbe-bfde-9e32c30d3ed2'::uuid, 'La pile d’appels d’un programme récursif est une file.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une pile : le dernier appel ouvert est le premier à se terminer.', 8),
    ('bdb7a281-38e6-5dcb-8947-37d56a309201'::uuid, '37ff85d0-c960-5ba0-a7d6-bbcff83acf41'::uuid, 'Quelle est la différence entre une classe et une instance ?', 'mcq', '["La classe est le modèle, l’instance un objet construit sur ce modèle","La classe contient les données, l’instance les méthodes","Il n’y a aucune différence","L’instance est une classe sans méthode"]'::jsonb, 0, 'La classe Compte décrit ce qu’est un compte ; mon compte est une instance.', 1),
    ('1f84727b-c3d3-5deb-8658-56d4b99aab5c'::uuid, '37ff85d0-c960-5ba0-a7d6-bbcff83acf41'::uuid, 'À quoi sert le paramètre self dans une méthode Python ?', 'mcq', '["Il désigne l’instance sur laquelle la méthode est appelée","Il représente la classe elle-même","Il déclare une variable globale","Il est purement décoratif"]'::jsonb, 0, 'Sans lui, on crée une variable locale qui disparaît à la fin de la méthode.', 2),
    ('06805432-a241-5920-a60c-943912b85485'::uuid, '37ff85d0-c960-5ba0-a7d6-bbcff83acf41'::uuid, 'Quelle méthode spéciale Python est appelée à la création d’un objet ?', 'mcq', '["__init__","__new__","__str__","__call__"]'::jsonb, 0, 'C’est le constructeur : il initialise les attributs de l’instance.', 3),
    ('1d9df9ab-a466-5541-9f1a-da8bf77675bf'::uuid, '37ff85d0-c960-5ba0-a7d6-bbcff83acf41'::uuid, 'Qu’apporte l’encapsulation ?', 'mcq', '["La possibilité de changer la représentation interne sans casser le code utilisateur","Un gain de vitesse d’exécution","La réduction de la taille du programme","La suppression des erreurs de syntaxe"]'::jsonb, 0, 'C’est ce qui rend un programme modifiable dans la durée.', 4),
    ('4dbecc9e-f4f0-5ff2-8f1e-e46dcac5f1cb'::uuid, '37ff85d0-c960-5ba0-a7d6-bbcff83acf41'::uuid, 'Quelle relation l’héritage exprime-t-il ?', 'mcq', '["Une relation « est un »","Une relation « a un »","Une relation « contient »","Une relation « utilise »"]'::jsonb, 0, 'Pour « a un », il faut préférer la composition.', 5),
    ('c61b1a32-656a-5cea-871a-3ac1043921e6'::uuid, '37ff85d0-c960-5ba0-a7d6-bbcff83acf41'::uuid, 'En Python, un attribut préfixé d’un souligné est inaccessible de l’extérieur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est une convention, pas une contrainte : le langage ne l’interdit pas.', 6),
    ('27d0369b-5f78-5926-8dab-c2643f4b07cc'::uuid, '37ff85d0-c960-5ba0-a7d6-bbcff83acf41'::uuid, 'Qu’est-ce que le polymorphisme ?', 'mcq', '["Une même méthode se comporte différemment selon le type réel de l’objet","Une classe qui hérite de plusieurs classes","Un attribut de plusieurs types","Une fonction à nombre variable d’arguments"]'::jsonb, 0, 'Il permet un traitement unique sur une collection d’objets hétérogènes.', 7),
    ('27d21d3f-d8b5-58b0-bd6b-e64385b538ac'::uuid, '37ff85d0-c960-5ba0-a7d6-bbcff83acf41'::uuid, 'Un attribut de classe est partagé par toutes les instances.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Contrairement à l’attribut d’instance, propre à chaque objet.', 8),
    ('3c4880e6-476c-5619-a08c-a2a38f3bcc39'::uuid, '85ca5140-0f1f-5b5d-96b6-f546c98084df'::uuid, 'Qu’est-ce que la hauteur d’un arbre ?', 'mcq', '["La longueur du plus long chemin de la racine à une feuille","Le nombre total de nœuds","Le nombre de feuilles","Le nombre d’enfants de la racine"]'::jsonb, 0, 'La taille, elle, compte les nœuds.', 1),
    ('42c91a3d-dd99-5fe6-9151-5cae1c5e3255'::uuid, '85ca5140-0f1f-5b5d-96b6-f546c98084df'::uuid, 'Quelle propriété définit un arbre binaire de recherche ?', 'mcq', '["Tout le sous-arbre gauche est inférieur au nœud, tout le sous-arbre droit lui est supérieur","Chaque nœud a exactement deux enfants","Toutes les feuilles sont au même niveau","Les valeurs sont stockées dans les feuilles"]'::jsonb, 0, 'C’est cette contrainte d’ordre qui permet la recherche par descente.', 2),
    ('c685f37c-91af-544a-8c9e-d71584e760e1'::uuid, '85ca5140-0f1f-5b5d-96b6-f546c98084df'::uuid, 'Quel parcours d’un ABR produit les valeurs triées ?', 'mcq', '["Le parcours infixe","Le parcours préfixe","Le parcours suffixe","Le parcours en largeur"]'::jsonb, 0, 'Gauche, nœud, droite : c’est la propriété la plus utile de cette structure.', 3),
    ('6c2e7c7a-1558-5c3e-aa19-e0c95944090f'::uuid, '85ca5140-0f1f-5b5d-96b6-f546c98084df'::uuid, 'Quelle structure utilise-t-on pour un parcours en largeur d’un arbre ?', 'mcq', '["Une file","Une pile","Un dictionnaire","Un arbre auxiliaire"]'::jsonb, 0, 'C’est le seul des quatre parcours qui ne s’écrit pas naturellement de façon récursive.', 4),
    ('5c4854bf-a27f-5c45-8bf7-e237fc8855c2'::uuid, '85ca5140-0f1f-5b5d-96b6-f546c98084df'::uuid, 'Que se passe-t-il si l’on insère des valeurs déjà triées dans un ABR ?', 'mcq', '["L’arbre dégénère en peigne et la recherche redevient linéaire","L’arbre reste parfaitement équilibré","L’insertion échoue","L’arbre se réorganise automatiquement"]'::jsonb, 0, 'C’est la raison d’être des arbres équilibrés.', 5),
    ('819d3ab6-3f0e-54fa-9e6c-b39c54042053'::uuid, '85ca5140-0f1f-5b5d-96b6-f546c98084df'::uuid, 'Un arbre binaire de hauteur h contient au plus 2^(h+1) − 1 nœuds.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Inversement, un arbre à n nœuds a une hauteur d’au moins log₂(n).', 6),
    ('3e7b4aa0-af5c-5dc2-8442-26294bf85094'::uuid, '85ca5140-0f1f-5b5d-96b6-f546c98084df'::uuid, 'La définition d’un arbre binaire est naturellement récursive.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Soit vide, soit un nœud portant une valeur et deux arbres binaires.', 7),
    ('1647bfb1-631f-570b-afd6-1de753a5649c'::uuid, '85ca5140-0f1f-5b5d-96b6-f546c98084df'::uuid, 'Quel est le coût d’une recherche dans un ABR équilibré à n nœuds ?', 'mcq', '["Logarithmique en n","Linéaire en n","Constant","Quadratique en n"]'::jsonb, 0, 'Le coût est proportionnel à la hauteur, qui vaut environ log₂(n).', 8),
    ('5163320a-bc9a-57d0-b354-cc736ab64be9'::uuid, '6f306d43-a879-502b-816c-0657cf556157'::uuid, 'Quelle représentation d’un graphe convient à un grand graphe creux ?', 'mcq', '["La liste d’adjacence","La matrice d’adjacence","Un arbre binaire","Un dictionnaire de matrices"]'::jsonb, 0, 'La matrice occupe une mémoire en n² quel que soit le nombre d’arêtes.', 1),
    ('b22a1bd5-22eb-56ec-8874-bce53661b385'::uuid, '6f306d43-a879-502b-816c-0657cf556157'::uuid, 'Quel parcours donne le plus court chemin dans un graphe non pondéré ?', 'mcq', '["Le parcours en largeur","Le parcours en profondeur","Le parcours infixe","L’algorithme de Dijkstra"]'::jsonb, 0, 'Il visite tous les voisins avant d’aller plus loin.', 2),
    ('5b9643cc-c8d0-5c90-b7e9-ace140cfa08e'::uuid, '6f306d43-a879-502b-816c-0657cf556157'::uuid, 'Quelle structure le parcours en profondeur utilise-t-il ?', 'mcq', '["Une pile, ou la récursivité","Une file","Un dictionnaire","Une matrice"]'::jsonb, 0, 'Le parcours en largeur, lui, utilise une file.', 3),
    ('ebadad10-91c6-5df6-ba01-da39b9e925aa'::uuid, '6f306d43-a879-502b-816c-0657cf556157'::uuid, 'Pourquoi faut-il marquer les sommets visités lors d’un parcours de graphe ?', 'mcq', '["Sans cela, un cycle fait boucler le programme indéfiniment","Pour accélérer le calcul","Pour économiser la mémoire","Pour respecter l’ordre alphabétique"]'::jsonb, 0, 'C’est l’erreur la plus fréquente à l’écrit.', 4),
    ('8ce5fb54-1541-53d9-b0d1-97b6162aee64'::uuid, '6f306d43-a879-502b-816c-0657cf556157'::uuid, 'Quelle condition l’algorithme de Dijkstra impose-t-il ?', 'mcq', '["Des poids d’arêtes positifs","Un graphe non orienté","Un graphe sans cycle","Un graphe connexe"]'::jsonb, 0, 'Il choisit à chaque étape le sommet non traité le plus proche.', 5),
    ('618f4263-8965-54b0-a983-f6b33c027938'::uuid, '6f306d43-a879-502b-816c-0657cf556157'::uuid, 'Un graphe connexe est un graphe où tout sommet est atteignable depuis tout autre.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le parcours en profondeur permet de repérer les composantes connexes.', 6),
    ('ed83b8bf-6e89-5ed9-8ce8-5902cc4b876e'::uuid, '6f306d43-a879-502b-816c-0657cf556157'::uuid, 'Quel est le degré d’un sommet ?', 'mcq', '["Son nombre de voisins","Sa distance à la racine","Le nombre de chemins qui le traversent","Le poids de ses arêtes"]'::jsonb, 0, 'Dans un graphe orienté, on distingue degré entrant et degré sortant.', 7),
    ('dc5eb9db-9274-5e15-bccd-9ef71dd6f0c2'::uuid, '6f306d43-a879-502b-816c-0657cf556157'::uuid, 'Un arbre est un cas particulier de graphe.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est un graphe connexe et sans cycle.', 8),
    ('266b7ce8-27fb-56e4-82d5-05e31ead787b'::uuid, '46983c3d-eb2d-5d4b-99ff-c888f0496604'::uuid, 'Qu’est-ce qu’une clé primaire ?', 'mcq', '["Un attribut qui identifie de façon unique chaque enregistrement","Le premier attribut de la table","Un attribut qui référence une autre table","Un attribut obligatoirement numérique"]'::jsonb, 0, 'Elle ne peut être ni nulle ni dupliquée.', 1),
    ('23944d74-b1fd-562e-b46f-83362d45215e'::uuid, '46983c3d-eb2d-5d4b-99ff-c888f0496604'::uuid, 'Qu’est-ce qu’une clé étrangère ?', 'mcq', '["Un attribut qui référence la clé primaire d’une autre table","Une clé venant d’une base externe","Un attribut chiffré","Un identifiant temporaire"]'::jsonb, 0, 'C’est elle qui relie les tables entre elles.', 2),
    ('61b05523-448a-506e-bce6-5e8b94d60367'::uuid, '46983c3d-eb2d-5d4b-99ff-c888f0496604'::uuid, 'Comment représente-t-on une relation « plusieurs à plusieurs » ?', 'mcq', '["Par une table intermédiaire portant les deux clés étrangères","Par une clé étrangère dans chacune des deux tables","Par une seule table fusionnée","Ce n’est pas représentable"]'::jsonb, 0, 'C’est le point le plus souvent manqué à l’écrit.', 3),
    ('d635b135-e65a-52c0-9cd3-1c89362553dc'::uuid, '46983c3d-eb2d-5d4b-99ff-c888f0496604'::uuid, 'Que garantit l’intégrité référentielle ?', 'mcq', '["Qu’une clé étrangère pointe vers un enregistrement existant","Que les données sont sauvegardées","Que la base est chiffrée","Que les requêtes sont rapides"]'::jsonb, 0, 'Elle interdit d’inscrire un élève dans une classe inexistante.', 4),
    ('6cd83a07-036a-5928-b8e6-ac157e8537aa'::uuid, '46983c3d-eb2d-5d4b-99ff-c888f0496604'::uuid, 'Quel problème une table unique et redondante provoque-t-elle ?', 'mcq', '["Des anomalies de mise à jour, d’insertion et de suppression","Une perte de performance uniquement","Une impossibilité de faire des requêtes","Un dépassement de mémoire"]'::jsonb, 0, 'Une occurrence oubliée lors d’une correction rend la base incohérente.', 5),
    ('2a200779-77f5-5552-ba5f-b33fc75ab3ef'::uuid, '46983c3d-eb2d-5d4b-99ff-c888f0496604'::uuid, 'Qui a proposé le modèle relationnel ?', 'mcq', '["Codd, en 1970","Turing, en 1936","Von Neumann, en 1945","Berners-Lee, en 1989"]'::jsonb, 0, 'Les tables y sont appelées relations, d’où le nom du modèle.', 6),
    ('e85ec011-e1c4-5429-9011-4ad598f980dd'::uuid, '46983c3d-eb2d-5d4b-99ff-c888f0496604'::uuid, 'Dans une relation « un à plusieurs », où se place la clé étrangère ?', 'mcq', '["Du côté « plusieurs »","Du côté « un »","Dans une table intermédiaire","Dans les deux tables"]'::jsonb, 0, 'Chaque élève porte l’identifiant de sa classe, et non l’inverse.', 7),
    ('1d350f0f-6e94-5bfe-b64d-bbdfcf122f55'::uuid, '46983c3d-eb2d-5d4b-99ff-c888f0496604'::uuid, 'Une contrainte de domaine limite les valeurs admissibles d’un attribut.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Une note comprise entre 0 et 20, par exemple.', 8),
    ('c48a4c20-efe6-5092-b5d8-609433036468'::uuid, 'fe7cff31-f16b-5e63-943e-228877eea1ad'::uuid, 'Que signifie NULL dans une base de données ?', 'mcq', '["L’absence de valeur","La valeur zéro","Une chaîne vide","Une erreur de saisie"]'::jsonb, 0, 'Toute comparaison avec NULL renvoie « inconnu », y compris NULL = NULL.', 1),
    ('196c19e5-ce28-574d-8a4c-b9d5b3c13c6c'::uuid, 'fe7cff31-f16b-5e63-943e-228877eea1ad'::uuid, 'Comment teste-t-on l’absence de valeur en SQL ?', 'mcq', '["Avec IS NULL","Avec = NULL","Avec == NULL","Avec NOT 0"]'::jsonb, 0, 'L’égalité ne fonctionne jamais avec NULL : c’est un piège récurrent.', 2),
    ('f09b625b-d16c-5bd8-b592-24fbf5326396'::uuid, 'fe7cff31-f16b-5e63-943e-228877eea1ad'::uuid, 'À quoi sert un index sur une colonne ?', 'mcq', '["À accélérer les recherches sur cette colonne","À trier définitivement la table","À garantir l’unicité","À chiffrer la colonne"]'::jsonb, 0, 'Il fait passer une recherche d’un coût linéaire à un coût logarithmique.', 3),
    ('ad42ec34-684a-511b-b2bf-afeacc589fa7'::uuid, 'fe7cff31-f16b-5e63-943e-228877eea1ad'::uuid, 'Quel est le prix d’un index ?', 'mcq', '["De l’espace disque et un ralentissement des insertions","Une perte de précision des données","Une limitation du nombre de lignes","Une baisse de sécurité"]'::jsonb, 0, 'On indexe les colonnes très souvent interrogées, pas toutes.', 4),
    ('a1fd229b-5a96-5846-8606-2661dadc0c26'::uuid, 'fe7cff31-f16b-5e63-943e-228877eea1ad'::uuid, 'Qu’est-ce qu’une vue ?', 'mcq', '["Une requête enregistrée sous un nom, utilisable comme une table","Une copie de sauvegarde","Un index particulier","Une interface graphique"]'::jsonb, 0, 'Elle sert aussi à restreindre l’accès à certaines colonnes.', 5),
    ('045e05b7-57f5-5341-8731-b45a75ba0e4d'::uuid, 'fe7cff31-f16b-5e63-943e-228877eea1ad'::uuid, 'Quelle commande SQL attribue un droit à un utilisateur ?', 'mcq', '["GRANT","ALLOW","PERMIT","SET"]'::jsonb, 0, 'REVOKE retire un droit précédemment accordé.', 6),
    ('81e6f055-b81a-5f4e-8db8-30fb3c1d831f'::uuid, 'fe7cff31-f16b-5e63-943e-228877eea1ad'::uuid, 'La clé primaire d’une table est indexée automatiquement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est ce qui rend la recherche par identifiant immédiate.', 7),
    ('0548614d-35c3-5d4c-b455-81cc17c0791c'::uuid, 'fe7cff31-f16b-5e63-943e-228877eea1ad'::uuid, 'Quel mot-clé SQL interdit qu’une colonne soit vide ?', 'mcq', '["NOT NULL","UNIQUE","CHECK","DEFAULT"]'::jsonb, 0, 'UNIQUE interdit les doublons, CHECK impose une condition sur les valeurs.', 8),
    ('4d30473a-7028-5d3f-9cc8-5f1417327334'::uuid, 'd73afdc0-7b8a-5a86-8747-c116d825e1ac'::uuid, 'Qu’est-ce qu’une transaction ?', 'mcq', '["Un ensemble d’opérations traité comme un tout indivisible","Une requête de lecture","Un échange entre deux serveurs","Une sauvegarde périodique"]'::jsonb, 0, 'Un virement doit débiter et créditer ensemble, ou ne rien faire.', 1),
    ('d5298bc3-1eea-50f3-b9e4-e806ca45cf2a'::uuid, 'd73afdc0-7b8a-5a86-8747-c116d825e1ac'::uuid, 'Que signifient les propriétés ACID ?', 'mcq', '["Atomicité, Cohérence, Isolation, Durabilité","Accès, Concurrence, Index, Données","Authentification, Chiffrement, Intégrité, Disponibilité","Analyse, Compilation, Interprétation, Déploiement"]'::jsonb, 0, 'Elles définissent ce qu’un SGBD transactionnel garantit.', 2),
    ('4a34aee4-8fe5-5070-9380-f716512a28b3'::uuid, 'd73afdc0-7b8a-5a86-8747-c116d825e1ac'::uuid, 'Quelle commande SQL annule une transaction en cours ?', 'mcq', '["ROLLBACK","COMMIT","DELETE","REVOKE"]'::jsonb, 0, 'COMMIT, à l’inverse, la valide définitivement.', 3),
    ('ca6b089e-1b55-583f-9371-b46854139646'::uuid, 'd73afdc0-7b8a-5a86-8747-c116d825e1ac'::uuid, 'Pourquoi vaut-il mieux placer les contraintes dans le SGBD que dans l’application ?', 'mcq', '["Elles s’appliquent alors à tous les clients, présents et futurs","Elles s’exécutent plus vite","Elles sont plus faciles à écrire","Elles évitent d’écrire du SQL"]'::jsonb, 0, 'Une contrainte applicative ne protège que cette application.', 4),
    ('025c5ede-2cc3-565f-9576-c2108150f1f5'::uuid, 'd73afdc0-7b8a-5a86-8747-c116d825e1ac'::uuid, 'Que garantit la propriété d’isolation ?', 'mcq', '["Deux transactions simultanées se déroulent comme si elles étaient successives","Les données sont chiffrées","La base est inaccessible pendant l’écriture","Chaque utilisateur a sa propre base"]'::jsonb, 0, 'Sans elle, deux clients pourraient écraser mutuellement leur travail.', 5),
    ('7493c90c-f050-5f2c-b43e-06aae31c6e6e'::uuid, 'd73afdc0-7b8a-5a86-8747-c116d825e1ac'::uuid, 'SQLite est un SGBD embarqué, sans serveur.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On le trouve dans les téléphones et les navigateurs.', 6),
    ('303dc595-7d99-5a9a-8020-288e882b7198'::uuid, 'd73afdc0-7b8a-5a86-8747-c116d825e1ac'::uuid, 'Qu’est-ce qui assure la durabilité d’une transaction validée ?', 'mcq', '["Le journal des transactions, écrit avant les données","La mémoire vive du serveur","L’index de la table","Le chiffrement du disque"]'::jsonb, 0, 'Il permet de rejouer les opérations après une panne.', 7),
    ('5af04671-77c0-5162-91b7-ea5b587a2b89'::uuid, 'd73afdc0-7b8a-5a86-8747-c116d825e1ac'::uuid, 'Dans une architecture client-serveur, le serveur constitue un point de défaillance unique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est la contrepartie de la centralisation des données.', 8),
    ('84dcfad9-2b8f-5c3a-aacd-2fd94afad0a5'::uuid, 'b18a9fea-05d7-5f47-80d4-9ea3b5df31ee'::uuid, 'SQL est un langage…', 'mcq', '["Déclaratif : on décrit le résultat voulu, pas la façon de l’obtenir","Impératif, comme Python","Fonctionnel","Orienté objet"]'::jsonb, 0, 'Le SGBD choisit lui-même le plan d’exécution.', 1),
    ('7cfb9806-c884-55db-a8ba-dace7da1ca82'::uuid, 'b18a9fea-05d7-5f47-80d4-9ea3b5df31ee'::uuid, 'Quelle est la différence entre WHERE et HAVING ?', 'mcq', '["WHERE filtre les lignes avant regroupement, HAVING filtre les groupes après","HAVING est plus rapide","WHERE ne fonctionne qu’avec SELECT","Il n’y a aucune différence"]'::jsonb, 0, 'C’est la distinction la plus demandée en évaluation.', 2),
    ('1bc56190-e6a4-5677-99f2-439c9db0c26b'::uuid, 'b18a9fea-05d7-5f47-80d4-9ea3b5df31ee'::uuid, 'Que fait un LEFT JOIN de plus qu’un JOIN ?', 'mcq', '["Il garde les lignes de gauche même sans correspondance, complétées par NULL","Il trie les résultats","Il supprime les doublons","Il joint trois tables à la fois"]'::jsonb, 0, 'C’est ce qu’il faut pour lister les élèves sans classe.', 3),
    ('b7cb0d76-8049-529d-a905-90fc698d0e42'::uuid, 'b18a9fea-05d7-5f47-80d4-9ea3b5df31ee'::uuid, 'Que produit une jointure dont on a oublié la condition ON ?', 'mcq', '["Un produit cartésien","Une erreur de syntaxe","Un résultat vide","Une jointure externe"]'::jsonb, 0, 'Chaque ligne de la première table est combinée à chaque ligne de la seconde.', 4),
    ('4d184b51-3dff-5c55-93b1-7ea2c02342b2'::uuid, 'b18a9fea-05d7-5f47-80d4-9ea3b5df31ee'::uuid, 'Que se passe-t-il si l’on écrit un DELETE sans clause WHERE ?', 'mcq', '["Toutes les lignes de la table sont supprimées","Rien, la requête est refusée","Seule la première ligne est supprimée","La table est verrouillée"]'::jsonb, 0, 'C’est l’erreur la plus coûteuse du langage.', 5),
    ('ad5c2aaf-e9ca-5ad0-83b8-9148bada0125'::uuid, 'b18a9fea-05d7-5f47-80d4-9ea3b5df31ee'::uuid, 'Quelle est la parade efficace contre l’injection SQL ?', 'mcq', '["Les requêtes paramétrées","Le filtrage des apostrophes","La vérification côté navigateur","Le chiffrement de la base"]'::jsonb, 0, 'La valeur ne peut alors jamais être interprétée comme du code.', 6),
    ('70d4accd-abb7-5456-a09e-0d53afd804d5'::uuid, 'b18a9fea-05d7-5f47-80d4-9ea3b5df31ee'::uuid, 'Quel mot-clé regroupe les lignes avant d’appliquer un agrégat ?', 'mcq', '["GROUP BY","ORDER BY","DISTINCT","JOIN"]'::jsonb, 0, 'AVG, SUM ou COUNT s’appliquent alors groupe par groupe.', 7),
    ('4461f259-3b08-5496-8dca-8f4131dd955d'::uuid, 'b18a9fea-05d7-5f47-80d4-9ea3b5df31ee'::uuid, 'Dans l’ordre logique d’exécution, SELECT s’applique avant WHERE.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY : SELECT vient tard.', 8),
    ('f30da35c-3a8b-57e7-9259-acc9db6f7391'::uuid, 'd88024f0-3918-5bb4-8cf8-9d2a86a77592'::uuid, 'Quel est l’ordre de tri appliqué par défaut par ORDER BY ?', 'mcq', '["Croissant (ASC)","Décroissant (DESC)","Aléatoire","L’ordre d’insertion"]'::jsonb, 0, 'DESC doit être précisé explicitement.', 1),
    ('d900dc0b-fd45-5250-baea-e2274fd16a6b'::uuid, 'd88024f0-3918-5bb4-8cf8-9d2a86a77592'::uuid, 'Que se passe-t-il si l’on utilise LIMIT sans ORDER BY ?', 'mcq', '["Les lignes renvoyées sont arbitraires","La requête échoue","Les premières lignes insérées sont renvoyées","Le tri est fait automatiquement sur la clé primaire"]'::jsonb, 0, 'Rien n’oblige le SGBD à respecter un ordre qu’on ne lui a pas demandé.', 2),
    ('bd88edc9-e2ca-5ac4-baf3-2ddbf20b08fd'::uuid, 'd88024f0-3918-5bb4-8cf8-9d2a86a77592'::uuid, 'À quoi sert le mot-clé AS ?', 'mcq', '["À donner un alias à une colonne, notamment calculée","À trier les résultats","À joindre deux tables","À créer un index"]'::jsonb, 0, 'L’alias peut ensuite être réutilisé dans ORDER BY.', 3),
    ('dba50dfb-8559-5326-9ccc-93b2e94cef1a'::uuid, 'd88024f0-3918-5bb4-8cf8-9d2a86a77592'::uuid, 'Que réalisent ensemble LIMIT et OFFSET ?', 'mcq', '["La pagination des résultats","Le regroupement des lignes","La jointure de deux tables","Le filtrage des doublons"]'::jsonb, 0, 'OFFSET saute un certain nombre de lignes avant d’en renvoyer LIMIT.', 4),
    ('15e9a2e3-125c-586a-a647-fdf48abe5df4'::uuid, 'd88024f0-3918-5bb4-8cf8-9d2a86a77592'::uuid, 'Peut-on trier sur plusieurs colonnes à la fois ?', 'mcq', '["Oui, la seconde départage les ex æquo de la première","Non, une seule colonne est possible","Oui, mais uniquement en ordre croissant","Seulement avec GROUP BY"]'::jsonb, 0, 'On peut aussi trier sur une colonne non affichée.', 5),
    ('138877a2-46bd-5e4b-aead-a47386fa1120'::uuid, 'd88024f0-3918-5bb4-8cf8-9d2a86a77592'::uuid, 'Un ORDER BY modifie l’ordre de stockage des lignes dans la table.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il ordonne le résultat d’une requête ; c’est l’index qui ordonne une structure auxiliaire.', 6),
    ('bc7bb874-3e8f-56eb-983f-168c2cdc3614'::uuid, 'd88024f0-3918-5bb4-8cf8-9d2a86a77592'::uuid, 'Quel est le coût théorique d’un tri par comparaison ?', 'mcq', '["De l’ordre de n log n","De l’ordre de n","De l’ordre de n²","Constant"]'::jsonb, 0, 'C’est la borne des tris par comparaison, atteinte par le tri fusion.', 7),
    ('aa603882-b573-52bb-ace2-319152777cbd'::uuid, 'd88024f0-3918-5bb4-8cf8-9d2a86a77592'::uuid, 'Trier un numéro stocké en TEXT le classe alphabétiquement.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, '« 10 » se retrouve alors avant « 9 » : le type des colonnes n’est pas décoratif.', 8),
    ('bd137ac2-1308-506e-b835-52fac34ad23a'::uuid, 'fc0e6fc1-9904-5e66-91a5-ab0b2ee88673'::uuid, 'Que postule l’architecture de von Neumann ?', 'mcq', '["Programmes et données partagent la même mémoire","Les programmes sont stockés séparément des données","Le processeur exécute plusieurs instructions à la fois","La mémoire est infinie"]'::jsonb, 0, 'C’est ce qui rend possibles compilateurs, systèmes d’exploitation et virus.', 1),
    ('7725fbd0-a5d4-5f19-8de4-f80021a862c9'::uuid, 'fc0e6fc1-9904-5e66-91a5-ab0b2ee88673'::uuid, 'Quelle est la différence entre compilation et interprétation ?', 'mcq', '["Le compilateur traduit une fois pour toutes, l’interpréteur exécute au fil de la lecture","Le compilateur est plus lent à l’exécution","L’interpréteur produit un exécutable","Il n’y a aucune différence"]'::jsonb, 0, 'Java combine les deux avec un code intermédiaire et une machine virtuelle.', 2),
    ('065db332-ad2e-5039-93ab-92ee864bae2f'::uuid, 'fc0e6fc1-9904-5e66-91a5-ab0b2ee88673'::uuid, 'Que signifie « une fonction est une donnée de première classe » ?', 'mcq', '["Elle peut être stockée, passée en argument et renvoyée","Elle est définie en premier dans le fichier","Elle est plus rapide que les autres","Elle ne peut pas être modifiée"]'::jsonb, 0, 'C’est ce qui permet de passer une clé de comparaison à une fonction de tri.', 3),
    ('914b1ffc-2dde-5327-9b03-86944a4f3631'::uuid, 'fc0e6fc1-9904-5e66-91a5-ab0b2ee88673'::uuid, 'Python est à typage dynamique et fort.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Il n’exige pas de déclarer les types, mais refuse d’additionner un entier et une chaîne.', 4),
    ('8b3ceb23-d9c3-5a5b-9d4b-54d8433c82e0'::uuid, 'fc0e6fc1-9904-5e66-91a5-ab0b2ee88673'::uuid, 'Que dit le problème de l’arrêt ?', 'mcq', '["Aucun algorithme ne peut décider si un programme quelconque s’arrête","Tout programme finit par s’arrêter","Un programme peut vérifier n’importe quel autre programme","Un interpréteur ne s’arrête jamais"]'::jsonb, 0, 'Démontré par Turing : la question est indécidable.', 5),
    ('476c0b67-bb48-592b-a614-27a6c6f673d2'::uuid, 'fc0e6fc1-9904-5e66-91a5-ab0b2ee88673'::uuid, 'Les annotations de type de Python sont vérifiées par l’interpréteur.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elles servent à la documentation et aux outils d’analyse statique.', 6),
    ('15fbbc04-d42f-576b-a2c6-b13613328ccf'::uuid, 'fc0e6fc1-9904-5e66-91a5-ab0b2ee88673'::uuid, 'Une même suite de bits peut représenter un entier ou une instruction.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Le type n’est pas dans la donnée, mais dans l’interprétation qu’on en fait.', 7),
    ('11a96be7-cd74-542c-969d-d356e28225e9'::uuid, 'fc0e6fc1-9904-5e66-91a5-ab0b2ee88673'::uuid, 'Quelle conséquence pratique le problème de l’arrêt a-t-il ?', 'mcq', '["Aucun outil ne prouvera automatiquement qu’un programme quelconque est correct","Les compilateurs sont inutiles","Les boucles infinies sont interdites","Les tests sont inutiles"]'::jsonb, 0, 'C’est pourquoi les tests restent indispensables.', 8),
    ('86f493da-b8c9-5957-81d0-b48d886a5ef1'::uuid, 'e4330372-c556-5ac0-a405-200a267c304b'::uuid, 'Qu’est-ce qu’un effet de bord ?', 'mcq', '["Une modification, par une fonction, de quelque chose en dehors d’elle-même","Une erreur d’exécution","Un retour de valeur inattendu","Un appel récursif trop profond"]'::jsonb, 0, 'Le paradigme fonctionnel cherche précisément à les éliminer.', 1),
    ('cdd65eaa-4303-5bd0-ab9a-9d46e76b486a'::uuid, 'e4330372-c556-5ac0-a405-200a267c304b'::uuid, 'Que signifie la transparence référentielle ?', 'mcq', '["Un appel peut être remplacé par sa valeur, sans changer le programme","Le code est lisible","Les variables sont globales","Les fonctions sont documentées"]'::jsonb, 0, 'Elle découle de l’absence d’effet de bord.', 2),
    ('08688e4c-7212-5a3a-944f-e73f9802d73d'::uuid, 'e4330372-c556-5ac0-a405-200a267c304b'::uuid, 'Quel paradigme convient à une interface graphique ?', 'mcq', '["L’événementiel","Le fonctionnel","L’impératif","Le logique"]'::jsonb, 0, 'Le flot d’exécution est décidé par les événements, pas par le programme.', 3),
    ('c4b91698-44ff-57d9-991d-99596a2494a8'::uuid, 'e4330372-c556-5ac0-a405-200a267c304b'::uuid, 'Python impose un seul paradigme de programmation.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il est multiparadigme : impératif, fonctionnel, objet et événementiel.', 4),
    ('a407c194-9383-5f97-8b6f-2f82364c18bf'::uuid, 'e4330372-c556-5ac0-a405-200a267c304b'::uuid, 'Pourquoi une fonction pure est-elle facile à tester ?', 'mcq', '["Elle ne dépend d’aucun contexte extérieur et donne toujours le même résultat","Elle est plus courte","Elle ne renvoie rien","Elle est compilée séparément"]'::jsonb, 0, 'Aucun état à préparer, aucun effet à vérifier ailleurs.', 5),
    ('7e54d5db-0efe-54e3-a11c-3786263a8f13'::uuid, 'e4330372-c556-5ac0-a405-200a267c304b'::uuid, 'Le choix d’un paradigme change ce que la machine peut calculer.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Tous sont équivalents en puissance : c’est la lisibilité et la maintenance qui changent.', 6),
    ('6efc5373-e153-5e26-94c9-6b41051e0259'::uuid, 'e4330372-c556-5ac0-a405-200a267c304b'::uuid, 'Quel principe le paradigme fonctionnel privilégie-t-il à la place des boucles ?', 'mcq', '["La récursivité","Les instructions conditionnelles","Les objets","Les gestionnaires d’événements"]'::jsonb, 0, 'Il évite ainsi la modification d’un compteur, donc un état mutable.', 7),
    ('d40348f2-cf62-529b-82a1-d7da1b0da5a4'::uuid, 'e4330372-c556-5ac0-a405-200a267c304b'::uuid, 'Quel paradigme convient le mieux à la modélisation d’un domaine appelé à durer ?', 'mcq', '["L’objet","L’impératif","L’événementiel","Le fonctionnel pur"]'::jsonb, 0, 'Encapsulation et héritage y facilitent la maintenance.', 8),
    ('5ab7c2d6-8455-571f-a38a-16c521e91ba5'::uuid, 'a2c3b8a0-e087-5e43-9894-03250f117a63'::uuid, 'Qu’est-ce que l’interface d’un module ?', 'mcq', '["Ce que le module promet, indépendamment de la façon dont il le réalise","Son code source complet","Son interface graphique","La liste de ses dépendances"]'::jsonb, 0, 'Cacher l’implémentation permet de la changer sans casser le code appelant.', 1),
    ('55ca082a-5ab5-58bc-b489-f14306d56c9f'::uuid, 'a2c3b8a0-e087-5e43-9894-03250f117a63'::uuid, 'Que signifie « faible couplage » ?', 'mcq', '["Les modules dépendent le moins possible les uns des autres","Les modules sont peu nombreux","Le code est peu commenté","Les fonctions sont courtes"]'::jsonb, 0, 'Il va de pair avec une forte cohésion à l’intérieur de chaque module.', 2),
    ('69a988e8-b6be-5bda-b8c1-324e564aa230'::uuid, 'a2c3b8a0-e087-5e43-9894-03250f117a63'::uuid, 'Pourquoi éviter d’importer tout le contenu d’un module dans l’espace courant ?', 'mcq', '["Deux modules peuvent définir le même nom, et le second écrase le premier silencieusement","C’est plus lent à l’exécution","Cela consomme trop de mémoire","Python l’interdit"]'::jsonb, 0, 'On perd aussi la trace de l’origine de chaque nom.', 3),
    ('ea44f5c6-1c6b-5e22-b2e5-18578d1f4ac5'::uuid, 'a2c3b8a0-e087-5e43-9894-03250f117a63'::uuid, 'Que doit décrire une bonne docstring ?', 'mcq', '["Le contrat de la fonction : ce qu’elle garantit","L’algorithme employé, ligne par ligne","L’auteur et la date","Les tests associés"]'::jsonb, 0, 'Décrire l’algorithme oblige à réécrire la docstring à chaque modification interne.', 4),
    ('5d3a127d-fd4d-5a61-ba5d-9d3056732bfb'::uuid, 'a2c3b8a0-e087-5e43-9894-03250f117a63'::uuid, 'Qu’est-ce qu’une précondition ?', 'mcq', '["Ce que l’appelant doit garantir avant l’appel","Ce que la fonction garantit en retour","Une variable globale","Un test unitaire"]'::jsonb, 0, 'La postcondition, elle, porte sur ce que la fonction renvoie.', 5),
    ('16b9429a-bd49-5bc9-92da-0d66fb6dfaff'::uuid, 'a2c3b8a0-e087-5e43-9894-03250f117a63'::uuid, 'L’instruction assert est un mécanisme de gestion d’erreur adapté à la production.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Elle peut être désactivée : elle sert au développement, pas à la robustesse en production.', 6),
    ('711b4147-d2b3-517b-9985-8f7f80f41bfd'::uuid, 'a2c3b8a0-e087-5e43-9894-03250f117a63'::uuid, 'Quel est le bon réflexe devant un besoin courant, comme un tri ou une date ?', 'mcq', '["Chercher une bibliothèque existante et éprouvée","Écrire sa propre implémentation","Copier du code trouvé en ligne","Éviter le problème"]'::jsonb, 0, 'Un code maison est presque toujours plus lent et moins sûr.', 7),
    ('0def0af4-7673-54c1-9287-8131d13a5d0c'::uuid, 'a2c3b8a0-e087-5e43-9894-03250f117a63'::uuid, 'Un module qui a besoin de connaître l’intérieur d’un autre est bien découpé.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'C’est le signe d’un couplage fort : toute modification de l’un touchera l’autre.', 8),
    ('57cf4ebc-11e4-5cde-a321-2f570d81809d'::uuid, 'fab42582-3f8c-5023-a523-2a7d9d62b883'::uuid, 'Que doit expliquer un bon commentaire ?', 'mcq', '["Pourquoi le code est ainsi, et non ce qu’il fait","Ce que fait chaque ligne","L’auteur et la date","La complexité de l’algorithme"]'::jsonb, 0, 'Un commentaire qui répète le code devient faux dès la première modification.', 1),
    ('700336dd-6519-5f2b-a124-3903acb17044'::uuid, 'fab42582-3f8c-5023-a523-2a7d9d62b883'::uuid, 'Que prouve un test unitaire réussi ?', 'mcq', '["Que le programme n’échoue pas sur les cas testés","Que le programme est correct","Que le programme est rapide","Que le code est bien nommé"]'::jsonb, 0, 'Dijkstra : les tests montrent la présence de bugs, jamais leur absence.', 2),
    ('04f5eaaa-7731-5e4f-8fb1-6a8311ee233f'::uuid, 'fab42582-3f8c-5023-a523-2a7d9d62b883'::uuid, 'Quels cas un jeu de tests doit-il couvrir ?', 'mcq', '["Le cas nominal, les cas limites et les cas d’erreur","Uniquement le cas nominal","Uniquement les cas d’erreur","Un cas choisi au hasard"]'::jsonb, 0, 'Liste vide, élément unique et borne exacte sont les oublis les plus fréquents.', 3),
    ('c0449e7e-6dff-5032-b959-78d2efeb0b95'::uuid, 'fab42582-3f8c-5023-a523-2a7d9d62b883'::uuid, 'Pourquoi la duplication de code est-elle un problème ?', 'mcq', '["Les deux copies évoluent séparément et un bug corrigé d’un côté subsiste de l’autre","Elle ralentit l’exécution","Elle consomme trop de mémoire","Elle empêche la compilation"]'::jsonb, 0, 'C’est une dette technique, à rembourser en factorisant.', 4),
    ('ff4e512b-0413-5c4f-9983-d1332a5da9c9'::uuid, 'fab42582-3f8c-5023-a523-2a7d9d62b883'::uuid, 'À quoi sert un système de gestion de versions comme git ?', 'mcq', '["À conserver l’historique, revenir en arrière et travailler à plusieurs","À sauvegarder automatiquement le disque","À compiler le code","À tester le programme"]'::jsonb, 0, 'Chaque enregistrement doit être petit et expliquer l’intention.', 5),
    ('585c9df0-64d9-5ed5-8e5a-95f851732e03'::uuid, 'fab42582-3f8c-5023-a523-2a7d9d62b883'::uuid, 'Les tests rendent la refactorisation possible.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Ils servent de filet : on peut modifier le code sans craindre de casser un comportement.', 6),
    ('03e18fe5-5ece-5f60-a330-c18d7e70bc5e'::uuid, 'fab42582-3f8c-5023-a523-2a7d9d62b883'::uuid, 'Comment savoir qu’une fonction fait plus d’une chose ?', 'mcq', '["Son nom contient « et »","Elle dépasse dix lignes","Elle a plus de deux paramètres","Elle est récursive"]'::jsonb, 0, 'Une fonction doit faire une seule chose, et son nom doit pouvoir le dire.', 7),
    ('584ddbac-6466-553d-88a3-7715277f5779'::uuid, 'fab42582-3f8c-5023-a523-2a7d9d62b883'::uuid, 'Un programme sans bug est nécessairement un programme réussi.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'S’il est conforme à une mauvaise spécification, il fait parfaitement la mauvaise chose.', 8),
    ('dfccc16f-1aea-5138-8094-59f05e4177a4'::uuid, '5a853acc-4005-560e-b3a5-4a71a37e5b13'::uuid, 'Quelle famille d’erreurs est la plus dangereuse ?', 'mcq', '["L’erreur de logique, car le programme s’exécute et donne un résultat faux","L’erreur de syntaxe","L’erreur d’exécution","Toutes sont équivalentes"]'::jsonb, 0, 'Rien ne la signale : ni l’interpréteur, ni un arrêt du programme.', 1),
    ('a02c1a39-0ddd-5baf-b886-7aa56069fcc0'::uuid, '5a853acc-4005-560e-b3a5-4a71a37e5b13'::uuid, 'Quelle étape de la correction d’un bug est le plus souvent oubliée ?', 'mcq', '["Ajouter un test qui échouait avant la correction","Reproduire l’erreur","Localiser la zone fautive","Corriger le code"]'::jsonb, 0, 'C’est elle qui empêche le bug de revenir.', 2),
    ('0b3d3687-4035-53c2-a5b8-039452bd737c'::uuid, '5a853acc-4005-560e-b3a5-4a71a37e5b13'::uuid, 'À quoi sert une assertion pendant la mise au point ?', 'mcq', '["Faire échouer le programme à l’endroit exact où une hypothèse est violée","Corriger automatiquement l’erreur","Documenter la fonction","Accélérer l’exécution"]'::jsonb, 0, 'Sans elle, l’erreur ne se manifeste souvent que bien plus loin.', 3),
    ('2922d9b1-8f24-5de6-9b83-7b7137f7a336'::uuid, '5a853acc-4005-560e-b3a5-4a71a37e5b13'::uuid, 'Attraper toutes les exceptions sans rien en faire est une bonne pratique.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Cela masque les bugs au lieu de les traiter : le programme continue sur un état incorrect.', 4),
    ('b918e979-a61a-5338-b23f-4775d0b8fad7'::uuid, '5a853acc-4005-560e-b3a5-4a71a37e5b13'::uuid, 'Que permet la journalisation, qu’un débogueur ne permet pas ?', 'mcq', '["Garder une trace en production, où le débogueur n’est pas disponible","Exécuter le programme pas à pas","Inspecter les variables en direct","Poser des points d’arrêt"]'::jsonb, 0, 'Les deux outils sont complémentaires, pas concurrents.', 5),
    ('d3ce653f-bb0b-511c-a3c0-44442b3c406f'::uuid, '5a853acc-4005-560e-b3a5-4a71a37e5b13'::uuid, 'Un message d’erreur indique l’endroit où le bug a été introduit.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il indique l’endroit où le problème est devenu visible, ce qui est rarement le même.', 6),
    ('8d4bc007-2b02-5d78-a46c-a1cb02e07781'::uuid, '5a853acc-4005-560e-b3a5-4a71a37e5b13'::uuid, 'Quelle erreur classique consiste à se tromper d’un rang sur un indice ?', 'mcq', '["L’erreur de borne","L’erreur de type","L’erreur de syntaxe","L’interblocage"]'::jsonb, 0, 'Elle guette toutes les boucles indexées et tous les découpages de listes.', 7),
    ('6ca98e98-e480-5f0c-b08b-f262b17f2bfd'::uuid, '5a853acc-4005-560e-b3a5-4a71a37e5b13'::uuid, 'Un programme correct mais trop lent peut être considéré comme défectueux.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'D’où l’intérêt d’estimer la complexité avant de coder.', 8),
    ('bccb2976-8fbd-5732-a72d-9321045634cf'::uuid, '20be98f5-dca5-5a2d-8e80-ba255d26ca10'::uuid, 'Quels sont les deux composants obligatoires d’un algorithme récursif ?', 'mcq', '["Un cas de base et un appel sur un cas strictement plus proche de ce cas","Une boucle et une condition","Deux appels récursifs","Une pile et une file"]'::jsonb, 0, 'Oublier l’un des deux produit une récursion infinie.', 1),
    ('c9017dc9-24c6-57b2-9852-72f5c7574015'::uuid, '20be98f5-dca5-5a2d-8e80-ba255d26ca10'::uuid, 'Que se passe-t-il en cas de récursion infinie ?', 'mcq', '["La pile d’appels déborde et le programme s’arrête","Le programme tourne indéfiniment sans erreur","Le résultat est faux mais le programme se termine","Python détecte l’erreur avant l’exécution"]'::jsonb, 0, 'Chaque appel en cours occupe une place en mémoire.', 2),
    ('3119bad6-b33e-50dc-a960-678eaedb6ff3'::uuid, '20be98f5-dca5-5a2d-8e80-ba255d26ca10'::uuid, 'Dans quel ordre les appels récursifs se terminent-ils ?', 'mcq', '["Du plus profond au plus superficiel","Dans l’ordre où ils ont été lancés","De façon indéterminée","Tous en même temps"]'::jsonb, 0, 'C’est le fonctionnement d’une pile : dernier entré, premier sorti.', 3),
    ('972bc390-009a-53a4-a3c6-475fb549b4cc'::uuid, '20be98f5-dca5-5a2d-8e80-ba255d26ca10'::uuid, 'Pourquoi une récursion sur un million d’éléments échoue-t-elle en Python ?', 'mcq', '["La profondeur de récursion est bornée, autour de mille appels par défaut","Le calcul est trop long","Python interdit la récursivité","La mémoire vive est insuffisante pour les données"]'::jsonb, 0, 'Une boucle passerait sans difficulté sur les mêmes données.', 4),
    ('023b7735-e568-540c-b7d4-7f5166324cf1'::uuid, '20be98f5-dca5-5a2d-8e80-ba255d26ca10'::uuid, 'Pourquoi la version naïve de Fibonacci est-elle si coûteuse ?', 'mcq', '["Chaque niveau relance deux appels, et les mêmes valeurs sont recalculées","Les nombres deviennent trop grands","La pile est trop petite","Le cas de base est mal choisi"]'::jsonb, 0, 'Le coût devient exponentiel : c’est ce que la programmation dynamique corrige.', 5),
    ('410b309b-a311-5cc7-be08-c3211f5d93b9'::uuid, '20be98f5-dca5-5a2d-8e80-ba255d26ca10'::uuid, 'Toute fonction récursive peut être réécrite de façon itérative.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Avec une boucle et une pile explicite : le choix est une question de lisibilité.', 6),
    ('1d06c724-b964-5c30-9286-ebf9db6dd46a'::uuid, '20be98f5-dca5-5a2d-8e80-ba255d26ca10'::uuid, 'Quelle structure de données se traite le plus naturellement par récursivité ?', 'mcq', '["L’arbre","Le tableau","La file","Le dictionnaire"]'::jsonb, 0, 'Sa définition est elle-même récursive : un nœud et deux arbres.', 7),
    ('4ee55a96-d888-584b-9afb-d2ada1088614'::uuid, '20be98f5-dca5-5a2d-8e80-ba255d26ca10'::uuid, 'Écrire une fonction récursive suppose de supposer qu’elle fonctionne déjà pour le cas plus petit.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est l’acte de foi qui rend la récursivité écrivable — et que la preuve par récurrence justifie.', 8),
    ('c970ee13-dd8f-5a17-b334-5b9b5225eddc'::uuid, '50bdb0e7-4e6e-5c0f-98df-fbedb90f813e'::uuid, 'Quelles sont les trois étapes de la stratégie « diviser pour régner » ?', 'mcq', '["Diviser, régner, combiner","Trier, chercher, fusionner","Découper, tester, corriger","Lire, calculer, écrire"]'::jsonb, 0, 'C’est l’étape de combinaison qui distingue les algorithmes entre eux.', 1),
    ('0c0251e8-d280-5712-9b57-4530fa378ca4'::uuid, '50bdb0e7-4e6e-5c0f-98df-fbedb90f813e'::uuid, 'Quelle condition la recherche dichotomique exige-t-elle ?', 'mcq', '["Que le tableau soit trié","Que le tableau soit de taille paire","Que les valeurs soient entières","Que le tableau soit indexé à partir de 1"]'::jsonb, 0, 'Sur un tableau non trié, elle renvoie un résultat faux sans rien signaler.', 2),
    ('2777ed15-da81-5aac-a471-beafc77b1cd3'::uuid, '50bdb0e7-4e6e-5c0f-98df-fbedb90f813e'::uuid, 'Quel est le coût d’une recherche dichotomique sur n éléments ?', 'mcq', '["Logarithmique","Linéaire","Quadratique","Constant"]'::jsonb, 0, 'Environ 20 comparaisons pour un million d’éléments.', 3),
    ('bf17d5e5-f877-52c8-aacf-b8d65e069e79'::uuid, '50bdb0e7-4e6e-5c0f-98df-fbedb90f813e'::uuid, 'Quel est le coût du tri fusion ?', 'mcq', '["n log n dans tous les cas","n² dans le pire cas","n dans le meilleur cas","Constant"]'::jsonb, 0, 'Log n niveaux de découpage, n opérations de fusion par niveau.', 4),
    ('fb9f2858-2a82-5e99-803e-b99122989a3c'::uuid, '50bdb0e7-4e6e-5c0f-98df-fbedb90f813e'::uuid, 'Quel est le principal inconvénient du tri fusion ?', 'mcq', '["Il utilise une mémoire supplémentaire proportionnelle à n","Il est instable","Il est lent sur des données triées","Il ne fonctionne que sur des entiers"]'::jsonb, 0, 'En contrepartie, il est stable et sa performance ne dépend pas des données.', 5),
    ('3b6b95db-f690-5d0c-bcba-0e31ce1dcc7b'::uuid, '50bdb0e7-4e6e-5c0f-98df-fbedb90f813e'::uuid, 'Un tri est dit stable quand deux éléments égaux gardent leur ordre d’origine.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'C’est une propriété du tri fusion, utile pour trier successivement sur plusieurs critères.', 6),
    ('191c422d-4224-5dbb-a3bc-ccc4a1ffc1fe'::uuid, '50bdb0e7-4e6e-5c0f-98df-fbedb90f813e'::uuid, 'Quand la stratégie « diviser pour régner » devient-elle inefficace ?', 'mcq', '["Quand les sous-problèmes se recouvrent et sont recalculés plusieurs fois","Quand les données sont trop petites","Quand le tableau est déjà trié","Quand la mémoire est limitée"]'::jsonb, 0, 'C’est alors la programmation dynamique qui prend le relais.', 7),
    ('64ad96fd-1b6f-5a41-94e7-aef9751e0d1b'::uuid, '50bdb0e7-4e6e-5c0f-98df-fbedb90f813e'::uuid, 'Sur un million d’éléments, un tri quadratique demande environ 10¹² opérations.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'Contre environ 2 × 10⁷ pour un tri en n log n : la différence est de nature, pas de degré.', 8),
    ('b440d59e-0449-5b21-96c8-483ad720163c'::uuid, 'da04130e-7c38-5d72-ba62-41fcdc4120f9'::uuid, 'Quelles sont les deux conditions d’application de la programmation dynamique ?', 'mcq', '["Sous-structure optimale et chevauchement des sous-problèmes","Données triées et taille connue","Récursivité et cas de base","Indépendance des sous-problèmes"]'::jsonb, 0, 'C’est le chevauchement qui la distingue de « diviser pour régner ».', 1),
    ('b1417080-7912-535f-b8aa-06d6109e7f5b'::uuid, 'da04130e-7c38-5d72-ba62-41fcdc4120f9'::uuid, 'Qu’est-ce que la mémoïsation ?', 'mcq', '["Garder l’écriture récursive et mémoriser chaque résultat déjà calculé","Remplir un tableau du plus petit au plus grand","Trier les données avant le calcul","Réduire la taille du problème de moitié"]'::jsonb, 0, 'C’est l’approche descendante : le code change à peine, le coût s’effondre.', 2),
    ('cf2bf53f-be84-556a-8e39-ca205564a018'::uuid, 'da04130e-7c38-5d72-ba62-41fcdc4120f9'::uuid, 'Quelle est l’approche ascendante de la programmation dynamique ?', 'mcq', '["Remplir un tableau des plus petits sous-problèmes vers les plus grands","Partir du résultat et remonter","Appeler la fonction récursivement","Diviser le problème en deux"]'::jsonb, 0, 'Plus rapide et sans risque de dépassement de pile, mais l’ordre est à déterminer.', 3),
    ('bbe856ac-f981-58ba-b436-9c856f415ac6'::uuid, 'da04130e-7c38-5d72-ba62-41fcdc4120f9'::uuid, 'Quel est le coût de Fibonacci calculé avec mémoïsation ?', 'mcq', '["Linéaire","Exponentiel","Quadratique","Logarithmique"]'::jsonb, 0, 'Chaque terme n’est calculé qu’une seule fois.', 4),
    ('cc0f310e-0ea2-5579-80b6-40525d7af864'::uuid, 'da04130e-7c38-5d72-ba62-41fcdc4120f9'::uuid, 'L’algorithme glouton donne toujours l’optimum pour le rendu de monnaie.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Avec des pièces de 1, 3 et 4, rendre 6 lui fait choisir trois pièces au lieu de deux.', 5),
    ('f8d3e0a4-0ca8-57be-926a-87c731237fbc'::uuid, 'da04130e-7c38-5d72-ba62-41fcdc4120f9'::uuid, 'Que troque-t-on en programmation dynamique ?', 'mcq', '["De la mémoire contre du temps","Du temps contre de la précision","De la lisibilité contre de la sécurité","Rien du tout"]'::jsonb, 0, 'Sur des tailles réalistes, l’échange est presque toujours favorable.', 6),
    ('2363c332-aeda-5f86-bfbe-a6722a210f14'::uuid, 'da04130e-7c38-5d72-ba62-41fcdc4120f9'::uuid, 'Quel signal doit faire penser à la programmation dynamique ?', 'mcq', '["Le même argument revient plusieurs fois dans l’arbre des appels récursifs","Le tableau est trié","La fonction est très longue","Les données sont volumineuses"]'::jsonb, 0, 'Dès qu’on le repère, un dictionnaire de mémoïsation suffit.', 7),
    ('ffb1b0f3-808d-5706-8b11-4b43ddfeecf5'::uuid, 'da04130e-7c38-5d72-ba62-41fcdc4120f9'::uuid, 'Le problème du sac à dos se résout par programmation dynamique.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'À l’aide d’un tableau à deux dimensions : objets en lignes, capacités en colonnes.', 8),
    ('f01c8f2e-13fd-5d3a-a0fc-d02138ab8fe9'::uuid, '559a9c7e-068a-5f79-833d-a9c07c2fc3cd'::uuid, 'Quel est le coût de l’algorithme naïf de recherche de sous-chaîne dans le pire cas ?', 'mcq', '["m × n comparaisons","n comparaisons","log n comparaisons","m + n comparaisons"]'::jsonb, 0, 'Chaque alignement peut aller presque au bout du motif avant d’échouer.', 1),
    ('9ef76613-e601-5048-b918-3793d359fff3'::uuid, '559a9c7e-068a-5f79-833d-a9c07c2fc3cd'::uuid, 'Dans quel sens l’algorithme de Boyer-Moore compare-t-il le motif ?', 'mcq', '["De droite à gauche","De gauche à droite","Du milieu vers les bords","Dans un ordre aléatoire"]'::jsonb, 0, 'C’est ce qui permet les grands décalages en cas d’échec.', 2),
    ('ddc96eb4-00e0-5899-b845-c846f2e1743b'::uuid, '559a9c7e-068a-5f79-833d-a9c07c2fc3cd'::uuid, 'De combien peut-on décaler en Boyer-Moore quand le caractère fautif n’apparaît pas dans le motif ?', 'mcq', '["De la longueur entière du motif","D’un caractère","De la moitié du motif","On ne peut pas décaler"]'::jsonb, 0, 'Des positions sont ainsi écartées sans jamais être examinées.', 3),
    ('fc5f3416-a6b8-567b-bdaf-060a748d8bc8'::uuid, '559a9c7e-068a-5f79-833d-a9c07c2fc3cd'::uuid, 'Quel est le coût garanti de l’algorithme de Knuth-Morris-Pratt ?', 'mcq', '["n + m dans tous les cas","m × n dans le pire cas","log n en moyenne","n² dans le pire cas"]'::jsonb, 0, 'Il ne revient jamais en arrière dans le texte.', 4),
    ('8aa88fb5-ffc8-5322-98bc-dac8a243a8e3'::uuid, '559a9c7e-068a-5f79-833d-a9c07c2fc3cd'::uuid, 'Que précalcule Knuth-Morris-Pratt ?', 'mcq', '["Pour chaque préfixe du motif, le plus long préfixe qui est aussi un suffixe","La position de chaque caractère du texte","Le nombre d’occurrences attendues","La table des décalages par caractère"]'::jsonb, 0, 'La table de décalage par caractère est celle de Boyer-Moore.', 5),
    ('421c0f85-a49e-57c4-b964-11a44d7b605e'::uuid, '559a9c7e-068a-5f79-833d-a9c07c2fc3cd'::uuid, 'Le prétraitement du motif n’est rentable que si le texte est bien plus long que le motif.', 'true_false', '["Vrai","Faux"]'::jsonb, 0, 'On investit m opérations pour économiser ensuite sur les n caractères du texte.', 6),
    ('46331fe5-4f63-560b-8bef-ecf339752886'::uuid, '559a9c7e-068a-5f79-833d-a9c07c2fc3cd'::uuid, 'Que faire si l’on doit effectuer de très nombreuses recherches dans un texte fixe ?', 'mcq', '["Construire un index une fois pour toutes","Utiliser l’algorithme naïf","Trier le texte","Découper le texte en deux"]'::jsonb, 0, 'Relire le texte à chaque recherche serait du gaspillage.', 7),
    ('a619bf60-818c-5917-b76c-a7d6670ce101'::uuid, '559a9c7e-068a-5f79-833d-a9c07c2fc3cd'::uuid, 'L’algorithme naïf tire parti des caractères déjà comparés lors d’un échec.', 'true_false', '["Vrai","Faux"]'::jsonb, 1, 'Il oublie tout et décale d’un seul cran : c’est exactement ce que KMP corrige.', 8)
  ) AS v(id, quiz_id, question, kind, options, correct_index, explanation, position)
-- Le quiz doit exister : si le NOT EXISTS ci-dessus a écarté un quiz (une
-- leçon en avait déjà un), ses questions ne partent pas dans le vide.
 WHERE EXISTS (SELECT 1 FROM public.quizzes qz WHERE qz.id = v.quiz_id)
ON CONFLICT (id) DO NOTHING;

-- 5. Sonde finale ----------------------------------------------------------
DO $$
DECLARE
  n_vides integer;
  n_chap  integer;
BEGIN
  SELECT count(*) INTO n_chap FROM public.chapters c
   JOIN public.subjects s ON s.id = c.subject_id
   WHERE s.slug IN ('nsi');
  SELECT count(*) INTO n_vides FROM public.subjects s
   WHERE s.slug IN ('nsi')
     AND NOT EXISTS (SELECT 1 FROM public.chapters c WHERE c.subject_id = s.id);
  IF n_vides > 0 THEN
    RAISE EXCEPTION 'Migration 254 incomplète : % matiere(s) encore sans chapitre', n_vides;
  END IF;
  RAISE NOTICE 'Migration 254 OK : % chapitres sur les matieres visees.', n_chap;
END $$;
